import { NgFor, NgIf } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Component, inject } from '@angular/core';

@Component({
  selector: 'app-student-list',
  imports: [NgFor, NgIf],
  templateUrl: './student-list.component.html',
  styleUrl: './student-list.component.css'
})
export class StudentListComponent {
  http = inject(HttpClient);
  students : any[] = [];
  loading: boolean = true;
  errorMessage: string | null = null;

  // ngOnInit(): void {
  //   this.http.get("http://localhost:7270/api/Student").subscribe((res:any) =>{
  //     this.students = res;
  //     console.log(this.students);
  //   });
  // }

  ngOnInit(): void {
    this.http.get<any[]>("http://localhost:7270/api/Student").subscribe({
      next: (data)=> {
        data.sort((a, b) => a.firstName.localeCompare(b.firstName, undefined, { sensitivity: 'base' }));
        this.students=data;
        this.loading = false;
      },
      error:(err)=>{
        this.loading = false;
        this.errorMessage = "Server Error : List can't be loaded right now."
      }
    });
  }  
}
