import { NgFor } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Component, OnInit } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute } from '@angular/router';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';

interface StudentMarkDTO {
  studentId: number;
  studentName: string;
  examRecordId: number;
  marksObtained: number;
}

interface ExamRecordDTO {
  id: number
  examName: string;
  examSubject: string;
  examMarks: number;
  examDate: string;        // or Date
  examLevel: string;
  examDescription: string;
}

@Component({
  selector: 'app-student-marks-entry',
  imports: [FormsModule, NgFor],
  templateUrl: './student-marks-entry.component.html',
  styleUrl: './student-marks-entry.component.css'
})
export class StudentMarksEntryComponent implements OnInit {
  markList: StudentMarkDTO[] = [];
  examDetails!: ExamRecordDTO;
  examId!: number;
  batchStartYear!: number;

  constructor(private route: ActivatedRoute, private http: HttpClient) { }

  ngOnInit() {
    this.examId = +this.route.snapshot.paramMap.get('examId')!;
    this.batchStartYear = +this.route.snapshot.paramMap.get('batchStartYear')!;

    this.http.get<StudentMarkDTO[]>(
      `http://localhost:7270/api/studentmark/byExamAndBatch`,
      { params: { examId: this.examId, batchStartYear: this.batchStartYear } }
    ).subscribe({
      next: (data) => {
        data.sort((a:StudentMarkDTO,b:StudentMarkDTO)=> a.studentName.toLowerCase().localeCompare(b.studentName.toLowerCase()));
        //data.sort((a: StudentMarkDTO, b: StudentMarkDTO) => b.marksObtained - a.marksObtained);
        this.markList = data
      },
      error: (err) => {
      }
    });

    this.http.get<ExamRecordDTO>("http://localhost:7270/api/ExamRecord/examDetails", { params: { id: this.examId } }).subscribe({
      next: (data) => { this.examDetails = data },
      error: (err) => { }
    });
  }

  submitMarks() {
    this.http.post('http://localhost:7270/api/studentmark/batchSubmit', this.markList).subscribe(() => {
      alert('Marks submitted successfully!');
    });
  }

  downloadPDF() {
    const doc = new jsPDF();
    const title = 'Exam Report';
    doc.setFontSize(16);
    doc.setFont('helvetica', 'bold');

    const pageWidth = doc.internal.pageSize.getWidth();     // Total page width
    const textWidth = doc.getTextWidth(title);              // Width of the title text
    const x = (pageWidth - textWidth) / 2;                  // Center position

    doc.text(title, x, 15);
    //const doc = new jsPDF();
    //doc.setFontSize(16);
    //doc.text("Exam Report",14,15);

    doc.setFontSize(12);
    const exam = this.examDetails;
    doc.setFont('times', 'italic'); 

    doc.text(`${exam.examSubject}`, 14, 30);
    doc.text(`Exam Name: ${exam.examName}`, 70, 30);       // X shifted to the right
    doc.text(`Exam Date: ${exam.examDate}`, 140, 30);
    doc.text(`Total Marks: ${exam.examMarks}`, 14, 40); // Adjust spacing as needed
    doc.text(`Level : ${exam.examLevel}`,70,40);

    // Second row: Description (spanning full width)
    //doc.text(`Description: ${exam.examDescription}`, 14, 50);
    const descriptionLines = doc.splitTextToSize(`Description: ${exam.examDescription}`, 180);
    doc.text(descriptionLines, 14, 50);
    const tableStartY = 50 + descriptionLines.length * 6;
    
    const sortedList = [...this.markList].sort((a, b) => b.marksObtained - a.marksObtained);
    
    const headers = [['Sl.No.', 'Name', 'Marks']];
    const rows = sortedList.map((s,index) => [index+1, s.studentName, s.marksObtained]);

    autoTable(doc, {
      startY: tableStartY,
      head: headers,
      body: rows,
      theme: 'grid'
    });

    doc.save('Student_Report.pdf');
  }
}
